﻿'use strict';
(()=>{
const items=window.SKILLLANTERN_LIBRARY||[], root=document.body.dataset.root||'', key='skilllantern-saved-v1';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved=[];try{saved=JSON.parse(localStorage.getItem(key)||'[]').filter(id=>items.some(p=>p.id===id));}catch{}
const persist=()=>{try{localStorage.setItem(key,JSON.stringify(saved));}catch{}sync();};
function sync(){document.querySelectorAll('[data-save]').forEach(b=>{const yes=saved.includes(b.dataset.save);b.setAttribute('aria-pressed',String(yes));b.textContent=yes?'Saved · Remove':'+ Save'+(b.classList.contains('save-cap')?'':' to my setup');});document.querySelectorAll('[data-saved-count]').forEach(n=>n.textContent=saved.length);}
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-save]');if(b){const id=b.dataset.save;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];persist();filter();renderSetup();}});
const stopwords=new Set('a an the i me my we our you your ai want wants to do make build create use using with for of and or in on at is it that this real help can please need monthly check'.split(' '));
const aliases={financial:'finance',finances:'finance',writing:'document',write:'document',docs:'document',animations:'motion',animation:'motion',coding:'code',marketing:'marketing',reports:'report',websites:'website'};
const queryTerms=q=>q.toLowerCase().match(/[a-z0-9]+/g)?.filter(t=>!stopwords.has(t)).map(t=>aliases[t]||t)||[];
const searchScore=(text,terms)=>terms.reduce((score,t)=>score+(text.includes(t)?(['finance','3d','motion','website','marketing','spreadsheet','document'].includes(t)?3:1):0),0);
const form=document.getElementById('discover-form'),only=document.getElementById('saved-only');
function readURL(){if(!form)return;const params=new URLSearchParams(location.search);['q','app','task','kind'].forEach(k=>{const control=form.elements[k];control.value=params.get(k)||'';});only.checked=params.get('saved')==='1';filter(false);}
function filter(update=true){if(!form)return;const values=Object.fromEntries(new FormData(form)),q=(values.q||'').trim().toLowerCase(),terms=queryTerms(q);let count=0;document.querySelectorAll('[data-discovery-card]').forEach(c=>{const score=searchScore(c.dataset.text,terms);c.dataset.score=score;const match=(!q||terms.length>0&&score>0)&&(!values.app||c.dataset.apps.split('|').includes(values.app))&&(!values.task||c.dataset.tasks.split('|').includes(values.task))&&(!values.kind||c.dataset.kind===values.kind)&&(!only.checked||saved.includes(c.dataset.id));c.hidden=!match;if(match)count++;});const grid=document.querySelector('.discovery-grid');[...grid.children].sort((a,b)=>Number(b.dataset.score)-Number(a.dataset.score)).forEach(c=>grid.append(c));document.getElementById('discovery-count').textContent=`${count} ${count===1?'capability':'capabilities'}`;document.getElementById('discovery-empty').hidden=count!==0;if(update){const params=new URLSearchParams();for(const[k,v]of Object.entries(values))if(v.trim())params.set(k,v.trim());if(only.checked)params.set('saved','1');const query=params.toString();history.replaceState(null,'',location.pathname+(query?'?'+query:'')+location.hash);}document.querySelectorAll('[data-profile]').forEach(a=>{const url=new URL(a.href);url.searchParams.set('from',location.pathname.split('/').pop()+location.search);a.href=url.href;});}
if(form){form.addEventListener('input',()=>filter());form.addEventListener('change',()=>filter());only.addEventListener('change',()=>filter());form.addEventListener('submit',ev=>{ev.preventDefault();filter();});const reset=()=>{form.reset();only.checked=false;filter();form.elements.q.focus();};form.addEventListener('reset',()=>setTimeout(()=>{only.checked=false;filter();},0));document.querySelector('[data-reset]')?.addEventListener('click',reset);window.addEventListener('popstate',readURL);readURL();}
const back=document.querySelector('[data-back-explore]');if(back){const from=new URLSearchParams(location.search).get('from');if(from&&/^(index|skills)\.html(\?|$)/.test(from))back.href=root+from;}
function brief(selected){return 'MY SKILLLANTERN SETUP\nChoose one compatible capability first. Do not install across apps without checking the requirements.\n\n'+selected.map(p=>`${p.name}\nApp context: ${p.apps.join(', ')}\nTask: ${p.tasks.join(', ')}\nOriginal source: ${p.sourceUrl}\nReviewed: ${p.reviewedOn}; source review is not installation verification.\nRequirements:\n${p.requirements.map(v=>'- '+v).join('\n')}\nSetup steps:\n${p.setupSteps.map((v,i)=>`${i+1}. ${v}`).join('\n')}\nLimits:\n${p.limitations.map(v=>'- '+v).join('\n')}\n${p.guidePath?'Guide: '+new URL(root+p.guidePath,location.href).href:''}`).join('\n\n')+'\n\nTry one small task in a copy, inspect changes and requested permissions, then decide whether to keep it.';}
async function copy(text,status){try{await navigator.clipboard.writeText(text);status.textContent='Copied. Paste this into the compatible app named in the brief.';}catch{const area=document.createElement('textarea');area.value=text;area.setAttribute('aria-label','Setup brief to copy');area.className='copy-fallback';area.style.width='100%';area.rows=12;status.after(area);area.focus();area.select();status.textContent='Select and copy the brief below.';}}
const panel=document.getElementById('saved-setup');
function renderSetup(){if(!panel)return;const chosen=items.filter(p=>saved.includes(p.id));if(!chosen.length){panel.innerHTML='<div class="empty-state"><h2>Start with one useful upgrade.</h2><p>Browse the collection and save what fits your app and task.</p><a class="button" href="skills.html">Explore the full collection</a></div>';return;}panel.innerHTML='<div class="setup-actions"><button class="button" id="copy-setup">Copy my setup brief</button><button class="button secondary" id="download-setup">Download brief</button><button class="button secondary" id="clear-setup">Clear selection</button><a href="skills.html">Keep exploring</a></div><p class="copy-status" role="status" id="copy-status"></p>'+chosen.map(p=>`<article class="setup-card"><div><p class="cap-kind">${esc(p.kind)} · ${esc(p.apps.join(' / '))}</p><h2><a href="${esc(p.detailPath)}">${esc(p.name)}</a></h2><p>${esc(p.summary)}</p><p class="small">${esc(p.requirements.join(' · '))}</p><a class="button secondary" href="${esc(p.guidePath||p.detailPath+'#setup')}">${p.guidePath?'Follow setup guide':'Review setup steps'}</a> <button class="inline-button" data-save="${esc(p.id)}">Remove</button></div><button class="button secondary" data-copy-item="${esc(p.id)}">Copy setup brief</button></article>`).join('');const status=document.getElementById('copy-status');document.getElementById('copy-setup').onclick=()=>copy(brief(chosen),status);document.getElementById('download-setup').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([brief(chosen)],{type:'text/plain;charset=utf-8'}));a.download='skilllantern-setup.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);status.textContent='Downloaded your setup brief.';};document.getElementById('clear-setup').onclick=()=>{saved=[];persist();renderSetup();};panel.querySelectorAll('[data-copy-item]').forEach(b=>b.onclick=()=>copy(brief(items.filter(p=>p.id===b.dataset.copyItem)),status));sync();}
const profileId=location.pathname.split('/').pop().replace('.html','');const profile=items.find(p=>p.id===profileId);if(profile){const verdict=document.querySelector('.profile-verdict');if(verdict){const b=document.createElement('button');b.className='button secondary';b.textContent='Copy setup brief';const status=document.createElement('p');status.className='copy-status';status.setAttribute('role','status');b.onclick=()=>copy(brief([profile]),status);verdict.append(b,status);}}
window.addEventListener('storage',ev=>{if(ev.key===key){try{saved=JSON.parse(ev.newValue||'[]');}catch{saved=[];}sync();filter(false);renderSetup();}});sync();renderSetup();
})();
